// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address player, uint256 amount) public {
        vm.assume(amount == 10 wei);
        vm.assume(player != address(c.bank()));
        vm.assume(player != address(0));

        address bank = c.bank();
        uint256 bankBefore = bank.balance;

        vm.deal(player, 10 wei);
        vm.prank(player);
        c.play{value: 10 wei}();

        uint256 bankAfter = bank.balance;
        // If the player lost (random == 0), the bank gets 1 wei fee; otherwise bank balance unchanged
        assertTrue(bankAfter == bankBefore + 1 wei || bankAfter == bankBefore);
    }
}

